    if not red_label_bottles: return bottles[0]
    bottles.sort(key=lambda b: b.horizontal_center)
    for bottle in bottles:
        if bottle in red_label_bottles:
            left_neighbor = None
            right_neighbor = None
            for neighbor in bottles:
                if neighbor != bottle and neighbor.overlaps_with(bottle.left, bottle.lower, bottle.right, bottle.upper):
                    if neighbor.left < bottle.left and neighbor.right > bottle.left:
                        left_neighbor = neighbor
                    if neighbor.left < bottle.right and neighbor.right > bottle.right:
                        right_neighbor = neighbor
            if left_neighbor and right_neighbor:
                return bottle
    return bottles[0]

